    neighbors = set()
    for x, y in component:
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if (nx, ny) not in component:
                neighbors.add((nx, ny))
    return neighbors

